package shopcertificate.ui;

import shopcertificate.dao.*;
import shopcertificate.db.DatabaseConnection;
import shopcertificate.model.*;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;

public class MainFrame extends JFrame {
    private static final long serialVersionUID = 1L;
    private static final Color INK=new Color(37,76,76), PAPER=new Color(247,246,242), MUTED=new Color(115,115,110), GOLD=new Color(194,142,74);
    private static final String[] TYPES={"Bonafide Certificate","Character Certificate","Transfer Certificate","Migration Certificate","Enrollment Certificate","Fee Certificate","Provisional Certificate"};
    private static final String[] STATUSES={"Requested","Under Review","Processing","Issued"};
    private final DatabaseConnection db; private final StudentDAO students; private final CertificateRequestDAO requests; private final CardLayout cards=new CardLayout(); private final JPanel content=new JPanel(cards); private final JLabel pageTitle=new JLabel();
    public MainFrame(DatabaseConnection db,String username){this.db=db;students=new StudentDAO(db);requests=new CertificateRequestDAO(db);setTitle("Student Certificate Record System");setDefaultCloseOperation(EXIT_ON_CLOSE);setMinimumSize(new Dimension(990,650));setSize(1180,760);setLocationRelativeTo(null);
        getContentPane().setBackground(PAPER);setLayout(new BorderLayout());add(top(username),BorderLayout.NORTH);
        content.setBackground(PAPER);content.add(dashboard(),"Dashboard");content.add(studentPage(),"Students");content.add(requestPage(),"Requests");content.add(recordPage(),"Records");add(content,BorderLayout.CENTER);
        JLabel footer=new JLabel("Developed by Yuvansh Saini | PIET24CR033",SwingConstants.CENTER);footer.setFont(new Font("Segoe UI",Font.PLAIN,10));footer.setForeground(MUTED);footer.setBorder(BorderFactory.createEmptyBorder(8,0,9,0));add(footer,BorderLayout.SOUTH);showPage("Dashboard");
    }
    private JPanel top(String user){JPanel whole=new JPanel(new BorderLayout());whole.setBackground(Color.WHITE);JPanel brand=new JPanel(new BorderLayout());brand.setBackground(INK);brand.setBorder(BorderFactory.createEmptyBorder(15,28,13,24));JLabel name=new JLabel("STUDENT CERTIFICATE RECORD SYSTEM");name.setFont(new Font("Segoe UI",Font.BOLD,16));name.setForeground(Color.WHITE);JLabel office=new JLabel("ACADEMIC SERVICES  ·  RECORDS OFFICE");office.setFont(new Font("Segoe UI",Font.PLAIN,10));office.setForeground(new Color(218,208,185));brand.add(name,BorderLayout.NORTH);brand.add(office,BorderLayout.SOUTH);JPanel account=new JPanel(new FlowLayout(FlowLayout.RIGHT,18,19));account.setBackground(INK);JLabel who=new JLabel("Office user  ·  "+user);who.setForeground(Color.WHITE);JButton logout=new JButton("Log out");logout.addActionListener(e->{dispose();new LoginFrame(db).setVisible(true);});account.add(who);account.add(logout);brand.add(account,BorderLayout.EAST);whole.add(brand,BorderLayout.NORTH);
        JPanel nav=new JPanel(new FlowLayout(FlowLayout.LEFT,4,0));nav.setBackground(Color.WHITE);nav.setBorder(BorderFactory.createEmptyBorder(7,22,7,10));String[][] items={{"Dashboard","Dashboard"},{"Students","Students"},{"Certificate Requests","Requests"},{"Certificate Records","Records"},{"Search / History","Records"}};for(String[] item:items){JButton b=new JButton(item[0]);b.setFont(new Font("Segoe UI",Font.PLAIN,13));b.setForeground(INK);b.setBackground(Color.WHITE);b.setBorder(BorderFactory.createEmptyBorder(10,14,10,14));b.setFocusPainted(false);b.addActionListener(e->showPage(item[1]));nav.add(b);}whole.add(nav,BorderLayout.SOUTH);return whole;}
    private void showPage(String page){pageTitle.setText(page);cards.show(content,page);}
    private JPanel base(String title,String subtitle){JPanel p=new JPanel(new BorderLayout(14,16));p.setBackground(PAPER);p.setBorder(BorderFactory.createEmptyBorder(24,30,20,30));JPanel h=new JPanel();h.setLayout(new BoxLayout(h,BoxLayout.Y_AXIS));h.setOpaque(false);JLabel t=new JLabel(title);t.setFont(new Font("Segoe UI",Font.BOLD,24));t.setForeground(new Color(37,37,37));JLabel s=new JLabel(subtitle);s.setFont(new Font("Segoe UI",Font.PLAIN,13));s.setForeground(MUTED);h.add(t);h.add(Box.createVerticalStrut(5));h.add(s);p.add(h,BorderLayout.NORTH);return p;}
    private JPanel dashboard(){JPanel p=base("Certificate Administration","Overview of student certificate requests and issuance.");JPanel body=new JPanel(new BorderLayout(0,20));body.setOpaque(false);JPanel metrics=new JPanel(new GridLayout(1,4,12,0));metrics.setOpaque(false);for(String status:STATUSES){JPanel box=new JPanel(new BorderLayout());box.setBackground(Color.WHITE);box.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0,3,0,0, status.equals("Issued")?new Color(63,125,90):GOLD),BorderFactory.createEmptyBorder(14,16,14,12)));JLabel l=new JLabel(status.toUpperCase());l.setForeground(MUTED);l.setFont(new Font("Segoe UI",Font.BOLD,11));JLabel n=new JLabel("—");n.setForeground(INK);n.setFont(new Font("Segoe UI",Font.BOLD,25));box.add(l,BorderLayout.NORTH);box.add(n,BorderLayout.CENTER);metrics.add(box);}body.add(metrics,BorderLayout.NORTH);
        JPanel recent=new JPanel(new BorderLayout(0,8));recent.setOpaque(false);JLabel label=new JLabel("RECENT CERTIFICATE REQUESTS");label.setFont(new Font("Segoe UI",Font.BOLD,13));label.setForeground(INK);recent.add(label,BorderLayout.NORTH);JTable table=table(new String[]{"Request ID","Student","Registration No.","Certificate","Request Date","Status"});recent.add(new JScrollPane(table),BorderLayout.CENTER);JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT));actions.setOpaque(false);JButton refresh=button("Refresh overview");refresh.addActionListener(e->loadDashboard(table,metrics));actions.add(refresh);recent.add(actions,BorderLayout.SOUTH);body.add(recent,BorderLayout.CENTER);p.add(body,BorderLayout.CENTER);loadDashboard(table,metrics);return p;}
    private void loadDashboard(JTable t,JPanel metrics){try{Map<String,Integer> counts=requests.counts();for(int i=0;i<4;i++){JPanel b=(JPanel)metrics.getComponent(i);((JLabel)b.getComponent(1)).setText(String.valueOf(counts.get(STATUSES[i])));}DefaultTableModel m=(DefaultTableModel)t.getModel();m.setRowCount(0);for(CertificateRequest r:requests.search("","All statuses","All types").stream().limit(10).toList())m.addRow(new Object[]{r.id(),r.studentName(),r.registrationNo(),r.certificateType(),r.requestDate(),r.status()});}catch(Exception e){showError(e);}}
    private JPanel studentPage(){JPanel p=base("Student Records","Maintain the student details used to identify certificate requests.");JPanel area=new JPanel(new BorderLayout(0,12));area.setOpaque(false);JPanel tools=new JPanel(new FlowLayout(FlowLayout.LEFT));tools.setOpaque(false);JTextField q=new JTextField(24);JButton search=button("Search"),add=button("Add student"),edit=button("Edit selected"),del=button("Delete selected");tools.add(new JLabel("Name or registration no."));tools.add(q);tools.add(search);tools.add(add);tools.add(edit);tools.add(del);JTable t=table(new String[]{"ID","Registration No.","Student Name","Course","Department","Semester","Email","Phone"});area.add(tools,BorderLayout.NORTH);area.add(new JScrollPane(t),BorderLayout.CENTER);p.add(area,BorderLayout.CENTER);
        Runnable reload=()->{try{fillStudents(t,students.search(q.getText().trim()));}catch(Exception ex){showError(ex);}};search.addActionListener(e->reload.run());q.addActionListener(e->reload.run());add.addActionListener(e->{Student s=studentDialog(null);if(s!=null)try{students.save(s);reload.run();}catch(Exception ex){showError(ex);}});edit.addActionListener(e->{Student old=selectedStudent(t);if(old==null)return;Student s=studentDialog(old);if(s!=null)try{students.save(s);reload.run();}catch(Exception ex){showError(ex);}});del.addActionListener(e->{Student s=selectedStudent(t);if(s==null)return;if(confirm("Delete student "+s.name()+"? Requests linked to the student prevent deletion."))try{students.delete(s.id());reload.run();}catch(Exception ex){showError(ex);}});reload.run();return p;}
    private void fillStudents(JTable t,List<Student> rows){DefaultTableModel m=(DefaultTableModel)t.getModel();m.setRowCount(0);for(Student s:rows)m.addRow(new Object[]{s.id(),s.registrationNo(),s.name(),s.course(),s.department(),s.semester(),s.email(),s.phone()});}
    private Student selectedStudent(JTable t){int row=t.getSelectedRow();if(row<0){warn("Select a student row first.");return null;}final int modelRow=t.convertRowIndexToModel(row);try{return students.search(t.getValueAt(modelRow,1).toString()).stream().filter(s->s.id()==Integer.parseInt(t.getValueAt(modelRow,0).toString())).findFirst().orElse(null);}catch(Exception ex){showError(ex);return null;}}
    private JPanel requestPage(){JPanel p=base("Certificate Requests","Register a request, then update its status as it moves through the records office.");JPanel area=new JPanel(new BorderLayout(0,12));area.setOpaque(false);JPanel tools=new JPanel(new FlowLayout(FlowLayout.LEFT));tools.setOpaque(false);JTextField q=new JTextField(18);JComboBox<String> status=new JComboBox<>(new String[]{"All statuses","Requested","Under Review","Processing","Issued"});JComboBox<String> type=new JComboBox<>(withAll(TYPES));JButton search=button("Search"),add=button("New request"),edit=button("Update selected"),del=button("Delete selected");tools.add(new JLabel("Search"));tools.add(q);tools.add(status);tools.add(type);tools.add(search);tools.add(add);tools.add(edit);tools.add(del);JTable t=requestTable();area.add(tools,BorderLayout.NORTH);area.add(new JScrollPane(t),BorderLayout.CENTER);p.add(area,BorderLayout.CENTER);Runnable reload=()->loadRequests(t,q.getText().trim(),status.getSelectedItem().toString(),type.getSelectedItem().toString());search.addActionListener(e->reload.run());q.addActionListener(e->reload.run());status.addActionListener(e->reload.run());type.addActionListener(e->reload.run());add.addActionListener(e->{CertificateRequest r=requestDialog(null);if(r!=null)try{requests.save(r);reload.run();}catch(Exception ex){showError(ex);}});edit.addActionListener(e->{CertificateRequest old=selectedRequest(t);if(old==null)return;CertificateRequest r=requestDialog(old);if(r!=null)try{requests.save(r);reload.run();}catch(Exception ex){showError(ex);}});del.addActionListener(e->{CertificateRequest r=selectedRequest(t);if(r!=null&&confirm("Delete request #"+r.id()+"?"))try{requests.delete(r.id());reload.run();}catch(Exception ex){showError(ex);}});reload.run();return p;}
    private JPanel recordPage(){JPanel p=requestPage();return p;}
    private void loadRequests(JTable t,String q,String s,String type){try{DefaultTableModel m=(DefaultTableModel)t.getModel();m.setRowCount(0);for(CertificateRequest r:requests.search(q,s,type))m.addRow(new Object[]{r.id(),r.studentName(),r.registrationNo(),r.certificateType(),r.requestDate(),r.status(),r.issueDate()==null?"—":r.issueDate(),r.remarks()});}catch(Exception e){showError(e);}}
    private CertificateRequest selectedRequest(JTable t){int row=t.getSelectedRow();if(row<0){warn("Select a request row first.");return null;}row=t.convertRowIndexToModel(row);try{int id=Integer.parseInt(t.getValueAt(row,0).toString());return requests.search(String.valueOf(id),"All statuses","All types").stream().filter(r->r.id()==id).findFirst().orElse(null);}catch(Exception ex){showError(ex);return null;}}
    private CertificateRequest requestDialog(CertificateRequest old){try{List<Student> all=students.search("");JComboBox<StudentChoice> student=new JComboBox<>();for(Student s:all)student.addItem(new StudentChoice(s));JComboBox<String> type=new JComboBox<>(TYPES),state=new JComboBox<>(STATUSES);JTextField date=new JTextField(old==null?LocalDate.now().toString():old.requestDate().toString(),15);JTextField issue=new JTextField(old==null?"":old.issueDate()==null?"":old.issueDate().toString(),15);JTextArea remarks=new JTextArea(old==null?"":old.remarks(),3,22);if(old!=null){for(int i=0;i<student.getItemCount();i++)if(student.getItemAt(i).value.id()==old.studentId())student.setSelectedIndex(i);type.setSelectedItem(old.certificateType());state.setSelectedItem(old.status());}JPanel f=form();field(f,"Student",student);field(f,"Certificate type",type);field(f,"Request date (YYYY-MM-DD)",date);field(f,"Status",state);field(f,"Issue date (optional)",issue);field(f,"Purpose / remarks",new JScrollPane(remarks));if(student.getItemCount()==0){warn("Add a student record before creating a certificate request.");return null;}if(JOptionPane.showConfirmDialog(this,f,old==null?"New certificate request":"Update certificate request",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE)!=JOptionPane.OK_OPTION)return null;LocalDate req=LocalDate.parse(date.getText().trim()),issued=issue.getText().trim().isEmpty()?null:LocalDate.parse(issue.getText().trim());if(state.getSelectedItem().equals("Issued")&&issued==null)issued=LocalDate.now();if(!state.getSelectedItem().equals("Issued"))issued=null;Student s=((StudentChoice)student.getSelectedItem()).value;return new CertificateRequest(old==null?0:old.id(),s.id(),s.name(),s.registrationNo(),type.getSelectedItem().toString(),req,remarks.getText().trim(),state.getSelectedItem().toString(),issued);}catch(java.sql.SQLException ex){showError(ex);return null;}catch(Exception ex){warn("Check the selected student and enter valid ISO dates (YYYY-MM-DD). Issue date is set when status is Issued.");return null;}}
    private Student studentDialog(Student old){JTextField reg=new JTextField(old==null?"":old.registrationNo(),19),name=new JTextField(old==null?"":old.name(),19),course=new JTextField(old==null?"B.Tech.":old.course(),19),dept=new JTextField(old==null?"":old.department(),19),sem=new JTextField(old==null?"":String.valueOf(old.semester()),19),email=new JTextField(old==null?"":old.email(),19),phone=new JTextField(old==null?"":old.phone(),19);JPanel f=form();field(f,"Registration number",reg);field(f,"Student name",name);field(f,"Course",course);field(f,"Department",dept);field(f,"Semester (1–8)",sem);field(f,"Email",email);field(f,"Phone",phone);if(JOptionPane.showConfirmDialog(this,f,old==null?"Add student":"Edit student",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE)!=JOptionPane.OK_OPTION)return null;try{String e=email.getText().trim();int n=Integer.parseInt(sem.getText().trim());if(reg.getText().isBlank()||name.getText().isBlank()||course.getText().isBlank()||dept.getText().isBlank()||n<1||n>8||!e.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$")||!phone.getText().trim().matches("[+]?[0-9]{10,13}"))throw new IllegalArgumentException();return new Student(old==null?0:old.id(),reg.getText().trim(),name.getText().trim(),course.getText().trim(),dept.getText().trim(),n,e,phone.getText().trim());}catch(Exception ex){warn("Enter all required details, a valid email, a 10–13 digit phone number, and semester 1–8.");return null;}}
    private JPanel form(){JPanel p=new JPanel(new GridBagLayout());p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createEmptyBorder(12,18,12,18));return p;}
    private void field(JPanel p,String label,Component c){GridBagConstraints g=new GridBagConstraints();g.gridx=0;g.gridy=p.getComponentCount()/2;g.anchor=GridBagConstraints.WEST;g.insets=new Insets(5,4,5,12);p.add(new JLabel(label),g);g.gridx=1;g.fill=GridBagConstraints.HORIZONTAL;g.weightx=1;p.add(c,g);}
    private JTable table(String[] cols){JTable t=new JTable(new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}});style(t);return t;}
    private JTable requestTable(){return table(new String[]{"Request ID","Student","Registration No.","Certificate Type","Request Date","Status","Issue Date","Purpose / Remarks"});}
    private void style(JTable t){t.setRowHeight(30);t.setFont(new Font("Segoe UI",Font.PLAIN,12));t.setForeground(new Color(37,37,37));t.setBackground(Color.WHITE);t.setGridColor(new Color(235,234,228));t.setSelectionBackground(new Color(222,234,228));t.setSelectionForeground(INK);t.getTableHeader().setBackground(INK);t.getTableHeader().setForeground(Color.WHITE);t.getTableHeader().setFont(new Font("Segoe UI",Font.BOLD,12));t.setAutoCreateRowSorter(true);}
    private String[] withAll(String[] v){String[] n=new String[v.length+1];n[0]="All types";System.arraycopy(v,0,n,1,v.length);return n;}
    private JButton button(String text){JButton b=new JButton(text);b.setForeground(INK);b.setFocusPainted(false);return b;}
    private boolean confirm(String text){return JOptionPane.showConfirmDialog(this,text,"Confirm",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION;}
    private void warn(String text){JOptionPane.showMessageDialog(this,text,"Certificate records",JOptionPane.WARNING_MESSAGE);}
    private void showError(Exception ex){String detail=ex.getMessage();if(ex instanceof java.sql.SQLException sql&&sql.getSQLState()!=null&&sql.getSQLState().startsWith("23"))detail="This record conflicts with an existing registration number or a related certificate request.";JOptionPane.showMessageDialog(this,"The database operation could not be completed.\n"+detail,"Database error",JOptionPane.ERROR_MESSAGE);}
    private record StudentChoice(Student value){public String toString(){return value.name()+"  ·  "+value.registrationNo();}}
}

